package cn.qiuc.invoice;

import org.junit.Test;
import java.util.*;
import static org.junit.Assert.*;

public class ReceiptRulesTest {
    private ReceiptRules.Project p(String id,String start,String end,String main,String...people){return new ReceiptRules.Project(id,start,end,main,List.of(people));}
    @Test public void pairingKeepsOrderedAddressesAndEightDigitCode(){var q=ReceiptRules.pairing("invoicepair:1?code=00123456&url=http%3A%2F%2F192.168.1.5%3A8769&url=http%3A%2F%2F10.0.0.3%3A8769");assertEquals("00123456",q.code());assertEquals(List.of("http://192.168.1.5:8769","http://10.0.0.3:8769"),q.urls());}
    @Test public void pairingRejectsBadVersionCodePublicHostsAndUnexpectedPaths(){for(String text:List.of("invoicepair:2?code=12345678&url=http://10.0.0.1:8769","invoicepair:1?code=1234&url=http://10.0.0.1:8769","invoicepair:1?code=12345678&code=87654321&url=http://10.0.0.1:8769","invoicepair:1?code=12345678&url=http://example.com:8769","invoicepair:1?code=12345678&url=http://8.8.8.8:8769","invoicepair:1?code=12345678&url=http://10.0.0.1:8765","invoicepair:1?code=12345678&url=http://10.0.0.1:8769/path","invoicepair:1?code=12345678&url=http://user@10.0.0.1:8769"))assertThrows(text,IllegalArgumentException.class,()->ReceiptRules.pairing(text));}
    @Test public void projectUsesUniqueDateThenLastThenFirst(){ReceiptRules.Project a=p("a","2026-10-01","2026-10-31",""),b=p("b","2026-11-01","","");assertEquals("b",ReceiptRules.project(List.of(a,b),"2026-11-01","a"));assertEquals("a",ReceiptRules.project(List.of(a,b),"2026-10-31","b"));var overlap=p("c","2026-10-01","","");assertEquals("b",ReceiptRules.project(List.of(a,b,overlap),"2026-11-01","b"));assertEquals("a",ReceiptRules.project(List.of(a,b,overlap),"2026-11-01","removed"));assertEquals("b",ReceiptRules.project(List.of(a,b),"2026-09-30","b"));assertEquals("a",ReceiptRules.project(List.of(a,b),"2026-09-30","removed"));assertEquals("",ReceiptRules.project(List.of(),"2026-11-01","a"));}
    @Test public void categoryUsesRecognitionThenLastThenOther(){assertEquals("酒店",ReceiptRules.category("酒店","高铁",Rules.CATEGORIES));assertEquals("高铁",ReceiptRules.category("其他","高铁",Rules.CATEGORIES));assertEquals("其他",ReceiptRules.category("unknown","old",Rules.CATEGORIES));}
    @Test public void changingProjectsNeverKeepsSomeoneFromAnotherProject(){ReceiptRules.Project a=p("a","","","lead","lead","last"),b=p("b","","","","b1"),c=p("c","","","removed","c1");assertEquals("lead",ReceiptRules.person(a,"last"));assertEquals("b1",ReceiptRules.person(b,"b1"));assertEquals("",ReceiptRules.person(b,"lead"));assertEquals("c1",ReceiptRules.person(c,"c1"));assertEquals("",ReceiptRules.person(null,"lead"));}
    @Test public void uploadOutcomesAndBoundedBackoff(){assertEquals("received",ReceiptRules.outcome(200));assertEquals("reselect",ReceiptRules.outcome(409));assertEquals("unpaired",ReceiptRules.outcome(401));assertEquals("pending",ReceiptRules.outcome(0));assertEquals("failed",ReceiptRules.outcome(400));assertEquals("failed",ReceiptRules.outcome(503));assertEquals(30000,ReceiptRules.delay(1));assertTrue(ReceiptRules.delay(3)>ReceiptRules.delay(2));assertEquals(21600000,ReceiptRules.delay(99));}
}
